const LIST_TOOL = 'mcp__proxy__list_requests'
const GET_TOOL = 'mcp__proxy__get_request'

const FILTER_HELP =
  'space-separated terms that must all hold, a leading "-" negates one: free text (substring of the URL), ' +
  'method:POST (or method:get,post), status:4xx | status:404 | status:>=400 | status:400-499, host:api.example.com | host:*.example.com, ' +
  'path:/v1/login, type:json|html|xml|js|css|img|font|media|text|form|ws|tunnel|other, is:error|ok|pending|tunnel|ws|https|rejected, client:192.168.'

const ACTION_TYPES = [
  'delay', 'throttle', 'setHeader', 'removeHeader', 'setQuery', 'removeQuery', 'mapRemote', 'replaceUrl',
  'setBody', 'replaceBody', 'mergeJson', 'respond', 'setStatus', 'fail', 'script',
]

const ACTION_SCHEMA = {
  type: 'object',
  description:
    'One step; its type and fields: delay {ms, msMax?} · throttle {bytesPerSecond} · setHeader {name, value} · removeHeader {name} · ' +
    'setQuery {name, value} (request) · removeQuery {name} (request) · mapRemote {scheme?, host?, port?, path?} (request: send elsewhere) · ' +
    'replaceUrl {pattern, with} (request) · setBody {text | json | file} · replaceBody {pattern, with} · mergeJson {json} (deep-merges into a JSON body) · ' +
    'respond {status, headers?, text | json | file} (request: answer without asking the server) · setStatus {status} (response) · ' +
    'fail {kind: reset | close | timeout} · script {code}. A replace pattern is re:<regex source> (every match, $1 works in with) or literal text. ' +
    'file is relative to the project root. script code is the body of async (req, res, ctx) => {}: in request it may change req.method, ' +
    'req.url, req.headers (lower-case names), req.body, or set req.respond = {status, headers, body}; in response it may change res.status, ' +
    'res.headers, res.body; req.json() and res.json() parse the bodies; a body may be set to an object. Prefer the other types to scripts.',
  properties: { type: { type: 'string', enum: ACTION_TYPES } },
  required: ['type'],
  additionalProperties: true,
}

const PATTERN_HELP = 'a glob (* any run, ? one character, case-insensitive, matched whole) or re:<JavaScript regex source>'

const RULE_SCHEMA = {
  type: 'object',
  properties: {
    id: { type: 'string', description: 'Unique in the file: 1-64 of letters, digits, ., _ and -.' },
    name: { type: 'string', description: 'A short title.' },
    description: { type: 'string', description: 'Why the rule exists, in one sentence the person reads.' },
    enabled: { type: 'boolean', description: 'false keeps the rule in the file without applying it.' },
    match: {
      type: 'object',
      description: `Every condition given must hold; no condition matches every request. Patterns are ${PATTERN_HELP}.`,
      properties: {
        url: { type: 'string', description: 'The full URL, e.g. https://api.example.com/v1/*' },
        host: { type: 'string', description: 'api.example.com, or *.example.com (which covers example.com too)' },
        path: { type: 'string', description: 'The path without the query, e.g. /v1/feed*' },
        methods: { type: 'array', items: { type: 'string' }, description: 'e.g. ["GET", "POST"]' },
        headers: { type: 'object', additionalProperties: { type: 'string' }, description: 'Request header name → pattern of its value' },
        query: { type: 'object', additionalProperties: { type: 'string' }, description: 'Query parameter → pattern of its value' },
        bodyContains: { type: 'string', description: 'Text the request body holds' },
        status: { type: 'string', description: 'Response only: 404, 4xx, >=400 or 500-599. A rule with it takes response steps only.' },
        contentType: { type: 'string', description: 'Response only: part of the response content type, e.g. json' },
      },
      additionalProperties: false,
    },
    request: { type: 'array', items: ACTION_SCHEMA, description: 'Steps on the request before it is sent, in order.' },
    response: { type: 'array', items: ACTION_SCHEMA, description: 'Steps on the response before the client gets it, in order.' },
    stop: { type: 'boolean', description: 'When this rule applies, the rules after it do not.' },
  },
  required: ['id'],
  additionalProperties: false,
}

async function rulesText($: EngineInterface): Promise<string> {
  const rules = await loadRules($)
  const flows = await read($, flowsAtom)
  const status = await read($, statusAtom)
  const lines = [
    `Rules file: ${rules.file}. ${rules.entries.length} rules; earlier rules apply first and every matching rule that is on chains.` +
      (status.phase === 'running' ? ' The proxy applies changes at once.' : ' The proxy is stopped; the rules apply once it runs.'),
    ...rules.fileErrors.map(error => `File error: ${error}`),
  ]
  rules.entries.forEach((entry, index) => {
    const hits = flows.filter(flow => flow.rules?.includes(entry.id)).length
    const state = entry.errors.length ? 'BROKEN' : entry.isUntrusted ? 'SCRIPT NOT APPROVED' : entry.enabled ? 'on' : 'off'
    lines.push(`${index + 1}. ${entry.id} [${state}]${entry.name ? ` ${entry.name}` : ''} · ${hits} hits`)
    if (entry.description) lines.push(`   ${entry.description}`)
    if (entry.summary) lines.push(`   ${entry.summary}`)
    for (const error of entry.errors) lines.push(`   error: ${error}`)
  })
  return lines.join('\n')
}

function optionsOf(raw: Record<string, unknown>): Options {
  const number = (value: unknown, fallback: number) => (Number.isFinite(Number(value)) && Number(value) > 0 ? Number(value) : fallback)
  return {
    port: number(raw.port, 8899),
    listen: raw.listen === 'lan' ? 'lan' : 'local',
    noDecrypt: typeof raw.noDecrypt === 'string' ? raw.noDecrypt : '',
    maxFlows: number(raw.maxFlows, 2000),
    node: typeof raw.node === 'string' && raw.node.trim() ? raw.node.trim() : 'node',
  }
}

async function statusText($: EngineInterface): Promise<string> {
  const status = await read($, statusAtom)
  const flows = await read($, flowsAtom)
  const lan = status.addresses.filter(a => a !== '127.0.0.1')
  switch (status.phase) {
    case 'running':
      return `Proxy is running on 127.0.0.1:${status.port}${status.host === '0.0.0.0' && lan.length ? ` and ${lan.map(a => `${a}:${status.port}`).join(', ')}` : ''}; ${flows.length} requests captured.`
    case 'starting':
      return `Proxy is starting on :${status.port}; ${flows.length} requests captured so far.`
    case 'failed':
      return `Proxy failed: ${(status.error ?? 'unknown error').replace(/\.+$/, '')}. ${flows.length} requests captured before that.`
    default:
      return `Proxy is stopped (the person starts it with /proxy). ${flows.length} requests captured earlier.`
  }
}

/** Shows the list or the tree, and remembers the choice for later sessions. */
async function chooseLayout($: EngineInterface, layout: 'list' | 'tree'): Promise<void> {
  await update($, viewAtom, (v): ProxyView => ({ ...v, mode: v?.mode === 'detail' ? 'list' : (v?.mode ?? 'list'), layout }))
  await $.store.set('layout', layout).catch(() => undefined)
}

async function openPane($: EngineInterface): Promise<void> {
  const opened = await $.ui.open({ id: PANE, title: 'Proxy', focus: true })
  if (!opened.isPlaced) $.ui.toast('proxy: the pane is waiting for room; widen the terminal')
}

export const register: Register = (on, raw) => {
  const options = optionsOf(raw as Record<string, unknown>)

  on('session.start', async ($, e, next) => {
    const started = await next(e)
    await $.command.register({
      name: 'proxy',
      description: 'HTTPS proxy: captured requests, filter, and setup for a browser, iOS and Android',
      argumentHint: '[start|stop|clear|setup|rules|status|tree|list]',
    })
    await $.tool.register({
      name: 'list_requests',
      description:
        'List the HTTP(S) requests captured by the Claude Code proxy the person runs with /proxy for their browser, iOS simulator/iPhone and Android emulator/phone. ' +
        'Returns the proxy status, then one line per request, oldest first: #id method status url response-size duration type, and the error if one. ' +
        'Status CERT means the client refused the proxy certificate. ' +
        `filter: ${FILTER_HELP}.`,
      inputSchema: {
        type: 'object',
        properties: {
          filter: { type: 'string', description: `Optional filter: ${FILTER_HELP}` },
          limit: { type: 'number', description: 'How many of the newest matching requests to list (default 50, at most 500).' },
        },
      },
    })
    await $.tool.register({
      name: 'get_request',
      description:
        'Show one captured request in full by its id from list_requests: URL, status, timing, client, error, request and response headers, and the decoded (gunzipped) text bodies, cut at max_body_chars.',
      inputSchema: {
        type: 'object',
        properties: {
          id: { type: 'number', description: 'The request id, the number after # in list_requests.' },
          max_body_chars: { type: 'number', description: 'Most characters of each body to include (default 20000).' },
        },
        required: ['id'],
      },
    })
    await $.tool.register({
      name: 'list_rules',
      description:
        "List the proxy's rules (<project>/.claude/proxy-rules.json): order (priority), id, on/off, what each does in words, errors, and how many captured requests each changed.",
      inputSchema: { type: 'object', properties: {} },
    })
    await $.tool.register({
      name: 'add_rule',
      description:
        "Add a rule to the proxy's rules engine. A rule changes matching requests before they are sent and their responses before the client gets them: " +
        'delays, throttling, headers, query, sending elsewhere, mocked answers, rewritten or merged bodies, status codes, failed connections, scripts. ' +
        'Rules live in <project>/.claude/proxy-rules.json; earlier rules apply first and every matching rule chains. It applies at once while the proxy runs. ' +
        'Prefer declarative steps; a script you add here is approved to run. Answers the rule in words. Ids of changed requests show in list_requests.',
      inputSchema: {
        type: 'object',
        properties: {
          rule: RULE_SCHEMA,
          position: { type: 'number', description: '1-based place in the order; the first applies first. Default: last.' },
        },
        required: ['rule'],
      },
    })
    await $.tool.register({
      name: 'update_rule',
      description:
        'Change a proxy rule by id: replace any of its fields (match, request and response are replaced whole), turn it on or off, or move it in the order. Answers the rule in words.',
      inputSchema: {
        type: 'object',
        properties: {
          id: { type: 'string', description: 'The rule to change.' },
          changes: { ...RULE_SCHEMA, required: [], description: 'Fields to set; the others stay.' },
          enabled: { type: 'boolean', description: 'Turn the rule on or off.' },
          position: { type: 'number', description: '1-based place to move it to; the first applies first.' },
        },
        required: ['id'],
      },
    })
    await $.tool.register({
      name: 'remove_rule',
      description: 'Remove a proxy rule by id.',
      inputSchema: { type: 'object', properties: { id: { type: 'string' } }, required: ['id'] },
    })
    await loadRules($).catch(() => undefined)
    const remembered = await $.store.get('layout').catch(() => undefined)
    if (remembered === 'tree' || remembered === 'list') {
      await update($, viewAtom, (v): ProxyView => ({ ...v, layout: remembered }))
    }
    // A reload of the module took the sidecar with it; bring it back.
    if (await read($, wantedAtom)) await startProxy($, options)
    return started
  })

  on('session.end', async ($, e, next) => {
    if (e.reason !== 'clear') {
      await revertAndroid($)
      await stopProxy($)
    }
    return next(e)
  })

  on('command.run', { command: 'proxy' }, async ($, e) => {
    const arg = e.args.trim().toLowerCase()
    switch (arg) {
      case 'start':
        await startProxy($, options)
        return { text: 'The proxy is starting. /proxy opens the pane.' }
      case 'stop':
        await stopProxy($)
        return { text: 'The proxy is stopped.' }
      case 'clear':
        await clearFlows($)
        return { text: 'The request list is cleared.' }
      case 'status':
        return { text: await statusText($) }
      case 'rules':
        await openRules($)
        await openPane($)
        return { text: 'The Proxy pane shows the rules.' }
      case 'tree':
      case 'list':
        await chooseLayout($, arg)
        await update($, viewAtom, (v): ProxyView => ({ ...v, mode: 'list' }))
        await openPane($)
        return { text: `The Proxy pane shows the requests as a ${arg}.` }
      case 'setup':
        await update($, viewAtom, (v): ProxyView => ({ ...v, mode: 'setup' }))
        await openPane($)
        return { text: 'Client setup is open in the Proxy pane.' }
      case '':
        await openPane($)
        await startProxy($, options)
        return { text: 'The Proxy pane is open.' }
      default:
        return { text: `Unknown "${arg}". /proxy [start|stop|clear|setup|rules|status|tree|list]` }
    }
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, ($, e) => drawPane($, e, options))

  on('tool.call', { tool: 'mcp__proxy__list_rules' }, async $ => ({ result: await rulesText($) })).catch(() => ({
    deny: 'proxy: could not read the rules file; try again.',
  }))

  on('tool.call', { tool: 'mcp__proxy__add_rule' }, async ($, e) => {
    const rule = e.rule as Rule
    const errors = ruleErrors(rule)
    if (errors.length) return { result: `Not added:\n${errors.join('\n')}` }
    const failure = await editRules($, rules => {
      if (rules.some(other => other.id === rule.id)) return `A rule with the id ${rule.id} exists; choose another id or call update_rule.`
      const at = typeof e.position === 'number' ? Math.max(0, Math.min(rules.length, Math.floor(e.position) - 1)) : rules.length
      rules.splice(at, 0, rule)
      return rules
    })
    if (failure) return { result: `Not added: ${failure}` }
    await trustScripts($, scriptsOf(rule))
    await loadRules($)
    return { result: `Added ${rule.id}: ${describeRule(rule)}\n\n${await rulesText($)}` }
  }).catch(() => ({ deny: 'proxy: could not write the rules file; try again.' }))

  on('tool.call', { tool: 'mcp__proxy__update_rule' }, async ($, e) => {
    const id = String(e.id)
    let changed: Rule | undefined
    let problems: string[] = []
    const failure = await editRules($, rules => {
      const from = rules.findIndex(rule => rule.id === id)
      if (from < 0) return `No rule has the id ${id}.`
      const changes = (e.changes ?? {}) as Partial<Rule>
      const next: Rule = { ...rules[from]!, ...changes }
      if (typeof e.enabled === 'boolean') next.enabled = e.enabled
      problems = ruleErrors(next)
      if (problems.length) return 'invalid'
      if (next.id !== id && rules.some(rule => rule.id === next.id)) return `A rule with the id ${next.id} exists.`
      rules.splice(from, 1)
      const to = typeof e.position === 'number' ? Math.max(0, Math.min(rules.length, Math.floor(e.position) - 1)) : from
      rules.splice(to, 0, next)
      changed = next
      return rules
    })
    if (failure === 'invalid') return { result: `Not changed:\n${problems.join('\n')}` }
    if (failure || !changed) return { result: `Not changed: ${failure}` }
    await trustScripts($, scriptsOf(changed))
    await loadRules($)
    return { result: `Changed ${changed.id}: ${describeRule(changed)}\n\n${await rulesText($)}` }
  }).catch(() => ({ deny: 'proxy: could not write the rules file; try again.' }))

  on('tool.call', { tool: 'mcp__proxy__remove_rule' }, async ($, e) => {
    const id = String(e.id)
    const failure = await editRules($, rules => (rules.some(rule => rule.id === id) ? rules.filter(rule => rule.id !== id) : `No rule has the id ${id}.`))
    return { result: failure ? `Not removed: ${failure}` : `Removed ${id}.\n\n${await rulesText($)}` }
  }).catch(() => ({ deny: 'proxy: could not write the rules file; try again.' }))

  on('tool.call', { tool: LIST_TOOL }, async ($, e) => {
    const filter = typeof e.filter === 'string' ? e.filter : ''
    const limit = Math.min(500, Math.max(1, Math.floor(Number(e.limit) || 50)))
    const flows = await read($, flowsAtom)
    const parsed = parseFilter(filter)
    const matched = filterFlows(flows, filter)
    const shown = matched.slice(-limit)
    const lines = [
      await statusText($),
      parsed.errors.length ? `Unrecognised filter terms ignored: ${parsed.errors.join(', ')}.` : '',
      filter ? `${matched.length} match "${filter}"${matched.length > shown.length ? `, the newest ${shown.length} shown` : ''}.` : matched.length > shown.length ? `The newest ${shown.length} shown.` : '',
      shown.length ? flowTable(shown) : 'No requests.',
    ]
    return { result: lines.filter(Boolean).join('\n') }
  }).catch(() => ({ deny: 'proxy: could not read the captured requests; try again.' }))

  on('tool.call', { tool: GET_TOOL }, async ($, e) => {
    const id = Number(e.id)
    const maxChars = Math.max(200, Math.floor(Number(e.max_body_chars) || 20_000))
    const summary = (await read($, flowsAtom)).find(flow => flow.id === id)
    const detail = await loadDetail($, id)
    const flow = detail ?? summary
    if (!flow) return { result: `No captured request #${e.id}. Call list_requests for the ids.` }

    const out: string[] = []
    out.push(`#${flow.id} ${flow.method} ${detail?.url ?? flowUrl(flow)}`)
    out.push(
      `status: ${statusLabel(flow)}${detail?.statusMessage ? ` ${detail.statusMessage}` : ''} · state: ${flow.state} · ${formatDuration(flow.durationMs)} · sent ${formatSize(flow.reqSize)} · received ${formatSize(flow.resSize)} · ${new Date(flow.ts).toISOString()}${flow.client ? ` · client ${flow.client}` : ''}`,
    )
    if (flow.error) out.push(`error (${flow.errorCode ?? 'unknown'}): ${flow.error}`)
    if (!detail) {
      out.push('Headers and bodies are not on disk (yet).')
      return { result: out.join('\n') }
    }
    const section = async (title: string, headers: [string, string][], body: typeof detail.req, contentType: string | null) => {
      out.push('', `--- ${title} headers ---`, ...headers.map(([k, v]) => `${k}: ${v}`))
      const loaded = await loadBody($, body, contentType)
      if (loaded.text === null && loaded.note === null) return out.push(`--- ${title} body: none ---`)
      out.push(`--- ${title} body${loaded.note ? ` (${loaded.note})` : ''} ---`)
      if (loaded.text !== null) {
        const clipped = clip(prettyBody(loaded.text, contentType), Number.MAX_SAFE_INTEGER, maxChars)
        out.push(clipped.text)
        if (clipped.isClipped) out.push(`[cut at ${maxChars} characters; the whole body is in ${body?.file}]`)
      }
    }
    const reqType = detail.reqHeaders.find(([k]) => k.toLowerCase() === 'content-type')?.[1] ?? null
    await section('request', detail.reqHeaders, detail.req, reqType)
    await section('response', detail.resHeaders, detail.res, detail.contentType)
    return { result: out.join('\n') }
  }).catch(() => ({ deny: 'proxy: could not read that request from disk; try again.' }))
}

files.shared/rules.mjs:
// The rules engine's shared half: what a rules file holds, whether a rule
// matches a request or a response, and how a rule reads as text. Plain
// JavaScript with no Node API, so the sidecar (which applies rules) and the
// mod (which lists and edits them) read a file the same way.
//
// A rules file is `{ "rules": [Rule, ...] }`; its order is the priority, the
// first rule applying first. A rule:
//   { id, name?, description?, enabled?, match?, request?: Action[],
//     response?: Action[], stop? }

export const REQUEST_ACTIONS = [
  'delay', 'throttle', 'setHeader', 'removeHeader', 'setQuery', 'removeQuery',
  'mapRemote', 'replaceUrl', 'setBody', 'replaceBody', 'mergeJson', 'respond', 'fail', 'script',
]
export const RESPONSE_ACTIONS = [
  'delay', 'throttle', 'setStatus', 'setHeader', 'removeHeader',
  'setBody', 'replaceBody', 'mergeJson', 'fail', 'script',
]
const BODY_ACTIONS = new Set(['setBody', 'replaceBody', 'mergeJson', 'script'])
const MATCH_KEYS = ['url', 'host', 'path', 'methods', 'headers', 'query', 'bodyContains', 'status', 'contentType']
const ID = /^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$/

// --- patterns ---------------------------------------------------------------
//
// A pattern is a glob (`*` any run of characters, `?` one) matched whole and
// without regard to case, or a regular expression written `re:<source>`. (Not
// `/source/flags`: every path starts with a slash, and `/v1/login` would read
// as the expression `v1` with the flags `login`.)

export function isRegexPattern(pattern) {
  return typeof pattern === 'string' && pattern.startsWith('re:') && pattern.length > 3
}

const compiled = new Map()

export function toRegExp(pattern) {
  let regex = compiled.get(pattern)
  if (!regex) {
    regex = compile(pattern)
    if (compiled.size > 500) compiled.clear()
    compiled.set(pattern, regex)
  }
  return regex
}

function compile(pattern) {
  if (isRegexPattern(pattern)) return new RegExp(pattern.slice(3))
  const source = String(pattern)
    .replace(/[.+^${}()|[\]\\]/g, '\\$&')
    .replace(/\*/g, '.*')
    .replace(/\?/g, '.')
  return new RegExp(`^${source}$`, 'i')
}

function patternError(pattern, where) {
  if (typeof pattern !== 'string' || pattern === '') return `${where} must be a non-empty string`
  try {
    toRegExp(pattern)
    return null
  } catch (error) {
    return `${where}: ${error.message}`
  }
}

function matchesPattern(pattern, value) {
  return toRegExp(pattern).test(value)
}

function matchesHost(pattern, host) {
  // *.example.com covers example.com itself too
  if (!isRegexPattern(pattern) && pattern.startsWith('*.') && host.toLowerCase() === pattern.slice(2).toLowerCase()) return true
  return matchesPattern(pattern, host)
}

/** `404`, `4xx`, `>=400`, `<300`, `500-599`. */
export function statusMatcher(text) {
  const value = String(text).trim().toLowerCase()
  if (/^[1-5]xx$/.test(value)) {
    const base = Number(value[0]) * 100
    return status => status >= base && status < base + 100
  }
  if (/^\d{3}$/.test(value)) return status => status === Number(value)
  const range = /^(\d{3})-(\d{3})$/.exec(value)
  if (range) return status => status >= Number(range[1]) && status <= Number(range[2])
  const compare = /^(>=|<=|>|<)(\d{3})$/.exec(value)
  if (compare) {
    const n = Number(compare[2])
    const op = compare[1]
    return status => (op === '>=' ? status >= n : op === '<=' ? status <= n : op === '>' ? status > n : status < n)
  }
  return null
}

// --- validation ---------------------------------------------------------------

const isObject = value => value !== null && typeof value === 'object' && !Array.isArray(value)
const isString = value => typeof value === 'string'
const isNumber = (value, min, max) => typeof value === 'number' && Number.isFinite(value) && value >= min && value <= max

function bodySourceError(action, where) {
  const given = ['text', 'json', 'file'].filter(key => action[key] !== undefined)
  if (given.length !== 1) return `${where}: give exactly one of text, json, file`
  if (action.text !== undefined && !isString(action.text)) return `${where}: text must be a string`
  if (action.file !== undefined && (!isString(action.file) || action.file === '')) return `${where}: file must be a path`
  return null
}

function actionErrors(action, phase, where) {
  if (!isObject(action)) return [`${where} must be an object`]
  const allowed = phase === 'request' ? REQUEST_ACTIONS : RESPONSE_ACTIONS
  if (!allowed.includes(action.type)) {
    return [`${where}: type must be one of ${allowed.join(', ')} in ${phase} (got ${JSON.stringify(action.type)})`]
  }
  const errors = []
  const need = (ok, text) => {
    if (!ok) errors.push(`${where} (${action.type}): ${text}`)
  }
  switch (action.type) {
    case 'delay':
      need(isNumber(action.ms, 0, 600_000), 'ms must be a number from 0 to 600000')
      if (action.msMax !== undefined) need(isNumber(action.msMax, action.ms ?? 0, 600_000), 'msMax must be at least ms and at most 600000')
      break
    case 'throttle':
      need(isNumber(action.bytesPerSecond, 1, 1e10), 'bytesPerSecond must be a positive number')
      break
    case 'setHeader':
    case 'setQuery':
      need(isString(action.name) && action.name !== '', 'name must be a non-empty string')
      need(isString(action.value), 'value must be a string')
      break
    case 'removeHeader':
    case 'removeQuery':
      need(isString(action.name) && action.name !== '', 'name must be a non-empty string')
      break
    case 'mapRemote':
      need(['scheme', 'host', 'port', 'path'].some(key => action[key] !== undefined), 'give at least one of scheme, host, port, path')
      if (action.scheme !== undefined) need(action.scheme === 'http' || action.scheme === 'https', 'scheme must be http or https')
      if (action.host !== undefined) need(isString(action.host) && action.host !== '', 'host must be a non-empty string')
      if (action.port !== undefined) need(isNumber(action.port, 1, 65535) && Number.isInteger(action.port), 'port must be 1 to 65535')
      if (action.path !== undefined) need(isString(action.path) && action.path.startsWith('/'), 'path must start with /')
      break
    case 'replaceUrl':
    case 'replaceBody': {
      const error = patternError(action.pattern, `${where} (${action.type}) pattern`)
      if (error) errors.push(error)
      need(isString(action.with), 'with must be a string')
      break
    }
    case 'setBody': {
      const error = bodySourceError(action, `${where} (setBody)`)
      if (error) errors.push(error)
      break
    }
    case 'mergeJson':
      need(isObject(action.json) || Array.isArray(action.json), 'json must be an object or an array')
      break
    case 'respond': {
      need(isNumber(action.status, 100, 599) && Number.isInteger(action.status), 'status must be 100 to 599')
      if (action.headers !== undefined) need(isObject(action.headers) && Object.values(action.headers).every(isString), 'headers must map names to strings')
      const given = ['text', 'json', 'file'].filter(key => action[key] !== undefined)
      need(given.length <= 1, 'give at most one of text, json, file')
      break
    }
    case 'setStatus':
      need(isNumber(action.status, 100, 599) && Number.isInteger(action.status), 'status must be 100 to 599')
      break
    case 'fail':
      need(['reset', 'close', 'timeout'].includes(action.kind), 'kind must be reset, close or timeout')
      break
    case 'script':
      need(isString(action.code) && action.code.trim() !== '', 'code must be a non-empty string')
      break
  }
  return errors
}

function matchErrors(match, where) {
  if (match === undefined) return []
  if (!isObject(match)) return [`${where} must be an object`]
  const errors = []
  for (const key of Object.keys(match)) {
    if (!MATCH_KEYS.includes(key)) errors.push(`${where}: unknown key ${JSON.stringify(key)} (known: ${MATCH_KEYS.join(', ')})`)
  }
  for (const key of ['url', 'host', 'path', 'contentType']) {
    if (match[key] !== undefined) {
      const error = patternError(match[key], `${where}.${key}`)
      if (error) errors.push(error)
    }
  }
  if (match.methods !== undefined && !(Array.isArray(match.methods) && match.methods.length > 0 && match.methods.every(isString))) {
    errors.push(`${where}.methods must be a non-empty list of strings`)
  }
  for (const key of ['headers', 'query']) {
    if (match[key] === undefined) continue
    if (!isObject(match[key])) errors.push(`${where}.${key} must map names to patterns`)
    else {
      for (const [name, pattern] of Object.entries(match[key])) {
        const error = patternError(pattern, `${where}.${key}.${name}`)
        if (error) errors.push(error)
      }
    }
  }
  if (match.bodyContains !== undefined && (!isString(match.bodyContains) || match.bodyContains === '')) {
    errors.push(`${where}.bodyContains must be a non-empty string`)
  }
  if (match.status !== undefined && !statusMatcher(match.status)) {
    errors.push(`${where}.status must look like 404, 4xx, >=400 or 500-599`)
  }
  return errors
}

/** What is wrong with one rule, as sentences; empty when nothing is. */
export function ruleErrors(rule, where = 'rule') {
  if (!isObject(rule)) return [`${where} must be an object`]
  const label = isString(rule.id) ? `rule ${rule.id}` : where
  const errors = []
  if (!isString(rule.id) || !ID.test(rule.id)) errors.push(`${label}: id must be 1-64 of letters, digits, ., _ and - (got ${JSON.stringify(rule.id)})`)
  for (const key of ['name', 'description']) {
    if (rule[key] !== undefined && !isString(rule[key])) errors.push(`${label}: ${key} must be a string`)
  }
  for (const key of ['enabled', 'stop']) {
    if (rule[key] !== undefined && typeof rule[key] !== 'boolean') errors.push(`${label}: ${key} must be true or false`)
  }
  errors.push(...matchErrors(rule.match, `${label}: match`))
  for (const phase of ['request', 'response']) {
    if (rule[phase] === undefined) continue
    if (!Array.isArray(rule[phase])) {
      errors.push(`${label}: ${phase} must be a list of actions`)
      continue
    }
    rule[phase].forEach((action, i) => errors.push(...actionErrors(action, phase, `${label}: ${phase}[${i}]`)))
  }
  if (!(rule.request?.length || rule.response?.length)) errors.push(`${label}: give at least one action in request or response`)
  const responseOnly = rule.match && (rule.match.status !== undefined || rule.match.contentType !== undefined)
  if (responseOnly && rule.request?.length) errors.push(`${label}: match.status and match.contentType are known only after the response, so such a rule takes response actions only`)
  return errors
}

/**
 * Reads a rules file's text. A rule with errors is kept, with its errors,
 * and never applied; `errors` holds the file's own problems.
 *
 * @returns `{ rules: [{ rule, errors }], errors }`
 */
export function parseRules(text) {
  if (text === null || text === undefined || String(text).trim() === '') return { rules: [], errors: [] }
  let data
  try {
    data = JSON.parse(text)
  } catch (error) {
    return { rules: [], errors: [`not valid JSON: ${error.message}`] }
  }
  if (!isObject(data) || !Array.isArray(data.rules)) return { rules: [], errors: ['the file must be {"rules": [...]}'] }
  const seen = new Set()
  const rules = data.rules.map((rule, index) => {
    const errors = ruleErrors(rule, `rules[${index}]`)
    if (isObject(rule) && isString(rule.id)) {
      if (seen.has(rule.id)) errors.push(`rule ${rule.id}: another rule has this id`)
      seen.add(rule.id)
    }
    return { rule, errors }
  })
  return { rules, errors: [] }
}

export function isEnabled(rule) {
  return rule.enabled !== false
}

// --- matching -----------------------------------------------------------------
//
// A request is `{ method, url, host, path, headers, body }`: `path` with its
// query, `headers` as [name, value] pairs, `body` the text when it was read.
// A response is `{ status, contentType }`.

function headerValue(headers, name) {
  const lower = name.toLowerCase()
  return headers.find(([key]) => key.toLowerCase() === lower)?.[1]
}

/** Whether the request-side conditions hold (status and contentType wait for the response). */
export function matchesRequest(rule, request) {
  const match = rule.match ?? {}
  if (match.methods && !match.methods.some(method => method.toUpperCase() === request.method.toUpperCase())) return false
  if (match.url && !matchesPattern(match.url, request.url)) return false
  if (match.host && !matchesHost(match.host, request.host)) return false
  if (match.path && !matchesPattern(match.path, request.path.split('?')[0])) return false
  if (match.headers) {
    for (const [name, pattern] of Object.entries(match.headers)) {
      const value = headerValue(request.headers, name)
      if (value === undefined || !matchesPattern(pattern, value)) return false
    }
  }
  if (match.query) {
    const params = new URLSearchParams(request.path.split('?').slice(1).join('?'))
    for (const [name, pattern] of Object.entries(match.query)) {
      const values = params.getAll(name)
      if (values.length === 0 || !values.some(value => matchesPattern(pattern, value))) return false
    }
  }
  if (match.bodyContains !== undefined && !(request.body ?? '').includes(match.bodyContains)) return false
  return true
}

export function matchesResponse(rule, response) {
  const match = rule.match ?? {}
  if (match.status !== undefined && !statusMatcher(match.status)(response.status)) return false
  if (match.contentType !== undefined) {
    const type = response.contentType ?? ''
    const pattern = match.contentType
    const holds = isRegexPattern(pattern) || pattern.includes('*') ? matchesPattern(pattern, type) : type.toLowerCase().includes(pattern.toLowerCase())
    if (!holds) return false
  }
  return true
}

/** The request's body must be read before the rule can match or act. */
export function needsRequestBody(rule) {
  return rule.match?.bodyContains !== undefined || (rule.request ?? []).some(action => BODY_ACTIONS.has(action.type))
}

/** The response's body must be held back so the rule can change it. */
export function needsResponseBody(rule) {
  return (rule.response ?? []).some(action => BODY_ACTIONS.has(action.type))
}

export function scriptsOf(rule) {
  return [...(rule.request ?? []), ...(rule.response ?? [])].filter(action => action?.type === 'script').map(action => action.code)
}

// --- text -------------------------------------------------------------------

function short(value, length = 40) {
  const text = typeof value === 'string' ? value : JSON.stringify(value)
  return text.length > length ? `${text.slice(0, length - 1)}…` : text
}

function duration(ms) {
  return ms >= 1000 && ms % 100 === 0 ? `${ms / 1000} s` : `${ms} ms`
}

function bytes(n) {
  return n >= 1024 * 1024 ? `${(n / 1024 / 1024).toFixed(1)} MB/s` : n >= 1024 ? `${Math.round(n / 1024)} KB/s` : `${n} B/s`
}

function bodySource(action) {
  if (action.file !== undefined) return `file ${action.file}`
  if (action.json !== undefined) return `JSON ${short(action.json)}`
  if (action.text !== undefined) return `"${short(action.text)}"`
  return 'an empty body'
}

export function describeAction(action) {
  switch (action?.type) {
    case 'delay':
      return action.msMax !== undefined && action.msMax > action.ms ? `wait ${duration(action.ms)} to ${duration(action.msMax)}` : `wait ${duration(action.ms)}`
    case 'throttle':
      return `throttle to ${bytes(action.bytesPerSecond)}`
    case 'setHeader':
      return `set header ${action.name}: ${short(action.value, 30)}`
    case 'removeHeader':
      return `remove header ${action.name}`
    case 'setQuery':
      return `set query ${action.name}=${short(action.value, 30)}`
    case 'removeQuery':
      return `remove query ${action.name}`
    case 'mapRemote': {
      const parts = [action.scheme && `${action.scheme}://`, action.host, action.port && `:${action.port}`, action.path].filter(Boolean)
      return `send to ${parts.join('')}`
    }
    case 'replaceUrl':
      return `rewrite URL ${action.pattern} → ${short(action.with, 30)}`
    case 'setBody':
      return `set body to ${bodySource(action)}`
    case 'replaceBody':
      return `replace ${action.pattern} with "${short(action.with, 30)}" in the body`
    case 'mergeJson':
      return `merge JSON ${short(action.json)}`
    case 'respond':
      return `answer ${action.status} with ${bodySource(action)} without asking the server`
    case 'setStatus':
      return `set status ${action.status}`
    case 'fail':
      return action.kind === 'timeout' ? 'never answer (time out)' : action.kind === 'reset' ? 'reset the connection' : 'close the connection'
    case 'script':
      return `run a script (${action.code.split('\n').length} lines)`
    default:
      return `unknown action ${JSON.stringify(action?.type)}`
  }
}

export function describeMatch(match = {}) {
  const parts = []
  if (match.methods) parts.push(match.methods.map(method => method.toUpperCase()).join(', '))
  if (match.url) parts.push(`URL ${match.url}`)
  if (match.host) parts.push(`host ${match.host}`)
  if (match.path) parts.push(`path ${match.path}`)
  for (const [name, pattern] of Object.entries(match.query ?? {})) parts.push(`query ${name}=${pattern}`)
  for (const [name, pattern] of Object.entries(match.headers ?? {})) parts.push(`header ${name}: ${pattern}`)
  if (match.bodyContains !== undefined) parts.push(`body has "${short(match.bodyContains, 30)}"`)
  if (match.status !== undefined) parts.push(`status ${match.status}`)
  if (match.contentType !== undefined) parts.push(`type ${match.contentType}`)
  return parts.length ? parts.join(' · ') : 'every request'
}

/** One line a person reads: what the rule catches and what it does there. */
export function describeRule(rule) {
  const phases = []
  if (rule.request?.length) phases.push(`before sending: ${rule.request.map(describeAction).join(', ')}`)
  if (rule.response?.length) phases.push(`on the response: ${rule.response.map(describeAction).join(', ')}`)
  return `${describeMatch(rule.match)} → ${phases.join('; ')}${rule.stop ? '; then stop' : ''}`
}

