// A QR code encoder for short text, so a phone can scan the proxy's setup
// address: byte mode, error correction level M, versions 1 to 10, the mask
// chosen by the standard's penalty rules (ISO/IEC 18004). A mod ships no
// dependencies, hence this file; it follows the structure of Project Nayuki's
// reference encoder.

export type QrCode = {
  /** Modules per side, the quiet zone not included. */
  size: number
  /** `modules[y][x]`: true for a dark module. */
  modules: boolean[][]
}

const MAX_VERSION = 10
// per version 1..10, error correction level M
const ECC_PER_BLOCK = [10, 16, 26, 18, 24, 16, 18, 22, 22, 26]
const BLOCKS = [1, 1, 1, 2, 2, 4, 4, 4, 5, 5]
const FORMAT_BITS_M = 0

function rawDataModules(version: number): number {
  let result = (16 * version + 128) * version + 64
  if (version >= 2) {
    const aligns = Math.floor(version / 7) + 2
    result -= (25 * aligns - 10) * aligns - 55
    if (version >= 7) result -= 36
  }
  return result
}

function dataCodewords(version: number): number {
  return Math.floor(rawDataModules(version) / 8) - ECC_PER_BLOCK[version - 1]! * BLOCKS[version - 1]!
}

function gfMultiply(x: number, y: number): number {
  let z = 0
  for (let i = 7; i >= 0; i--) {
    z = (z << 1) ^ ((z >>> 7) * 0x11d)
    z ^= ((y >>> i) & 1) * x
  }
  return z
}

function rsDivisor(degree: number): number[] {
  const result = new Array<number>(degree).fill(0)
  result[degree - 1] = 1
  let root = 1
  for (let i = 0; i < degree; i++) {
    for (let j = 0; j < result.length; j++) {
      result[j] = gfMultiply(result[j]!, root)
      if (j + 1 < result.length) result[j]! ^= result[j + 1]!
    }
    root = gfMultiply(root, 0x02)
  }
  return result
}

function rsRemainder(data: readonly number[], divisor: readonly number[]): number[] {
  const result = divisor.map(() => 0)
  for (const byte of data) {
    const factor = byte ^ result.shift()!
    result.push(0)
    divisor.forEach((coefficient, i) => {
      result[i]! ^= gfMultiply(coefficient, factor)
    })
  }
  return result
}

/** Splits the data into blocks, adds each block's error correction, interleaves. */
function withErrorCorrection(data: readonly number[], version: number): number[] {
  const blockCount = BLOCKS[version - 1]!
  const eccLength = ECC_PER_BLOCK[version - 1]!
  const raw = Math.floor(rawDataModules(version) / 8)
  const shortBlocks = blockCount - (raw % blockCount)
  const shortLength = Math.floor(raw / blockCount)
  const divisor = rsDivisor(eccLength)
  const blocks: number[][] = []
  for (let i = 0, k = 0; i < blockCount; i++) {
    const block = data.slice(k, k + shortLength - eccLength + (i < shortBlocks ? 0 : 1))
    k += block.length
    const ecc = rsRemainder(block, divisor)
    if (i < shortBlocks) block.push(0)
    blocks.push([...block, ...ecc])
  }
  const result: number[] = []
  for (let i = 0; i < blocks[0]!.length; i++) {
    blocks.forEach((block, j) => {
      // the padding byte of a short block is not sent
      if (i !== shortLength - eccLength || j >= shortBlocks) result.push(block[i]!)
    })
  }
  return result
}

function alignmentPositions(version: number, size: number): number[] {
  if (version === 1) return []
  const count = Math.floor(version / 7) + 2
  const step = Math.ceil((version * 4 + 4) / (count * 2 - 2)) * 2
  const result = [6]
  for (let position = size - 7; result.length < count; position -= step) result.splice(1, 0, position)
  return result
}

function masked(mask: number, x: number, y: number): boolean {
  switch (mask) {
    case 0: return (x + y) % 2 === 0
    case 1: return y % 2 === 0
    case 2: return x % 3 === 0
    case 3: return (x + y) % 3 === 0
    case 4: return (Math.floor(x / 3) + Math.floor(y / 2)) % 2 === 0
    case 5: return ((x * y) % 2) + ((x * y) % 3) === 0
    case 6: return (((x * y) % 2) + ((x * y) % 3)) % 2 === 0
    default: return (((x + y) % 2) + ((x * y) % 3)) % 2 === 0
  }
}

function penalty(modules: boolean[][]): number {
  const size = modules.length
  let score = 0
  const lines: string[] = []
  for (let y = 0; y < size; y++) lines.push(modules[y]!.map(dark => (dark ? '1' : '0')).join(''))
  for (let x = 0; x < size; x++) lines.push(modules.map(row => (row[x] ? '1' : '0')).join(''))
  for (const line of lines) {
    // runs of five or more of one color
    for (const run of line.match(/0{5,}|1{5,}/g) ?? []) score += 3 + run.length - 5
    // a pattern that looks like a finder, with light on either side
    const padded = `0000${line}0000`
    for (let i = 0; i + 11 <= padded.length; i++) {
      const window = padded.slice(i, i + 11)
      if (window === '10111010000' || window === '00001011101') score += 40
    }
  }
  // 2x2 blocks of one color
  for (let y = 0; y + 1 < size; y++) {
    for (let x = 0; x + 1 < size; x++) {
      const color = modules[y]![x]
      if (color === modules[y]![x + 1] && color === modules[y + 1]![x] && color === modules[y + 1]![x + 1]) score += 3
    }
  }
  // balance of dark and light
  const dark = modules.reduce((sum, row) => sum + row.filter(Boolean).length, 0)
  const total = size * size
  score += (Math.ceil(Math.abs(dark * 20 - total * 10) / total) - 1) * 10
  return score
}

export function encodeQr(text: string): QrCode {
  const bytes = [...new TextEncoder().encode(text)]
  let version = 1
  while (version <= MAX_VERSION && 4 + (version <= 9 ? 8 : 16) + bytes.length * 8 > dataCodewords(version) * 8) version++
  if (version > MAX_VERSION) throw new Error(`${bytes.length} bytes do not fit a version ${MAX_VERSION} QR code`)

  const bits: number[] = []
  const push = (value: number, length: number) => {
    for (let i = length - 1; i >= 0; i--) bits.push((value >>> i) & 1)
  }
  const capacity = dataCodewords(version) * 8
  push(0b0100, 4) // byte mode
  push(bytes.length, version <= 9 ? 8 : 16)
  for (const byte of bytes) push(byte, 8)
  push(0, Math.min(4, capacity - bits.length))
  push(0, (8 - (bits.length % 8)) % 8)
  for (let pad = 0xec; bits.length < capacity; pad ^= 0xec ^ 0x11) push(pad, 8)
  const data: number[] = []
  for (let i = 0; i < bits.length; i += 8) data.push(bits.slice(i, i + 8).reduce((byte, bit) => (byte << 1) | bit, 0))
  const codewords = withErrorCorrection(data, version)

  const size = version * 4 + 17
  const modules = Array.from({ length: size }, () => new Array<boolean>(size).fill(false))
  const isFunction = Array.from({ length: size }, () => new Array<boolean>(size).fill(false))
  const set = (x: number, y: number, dark: boolean) => {
    modules[y]![x] = dark
    isFunction[y]![x] = true
  }

  for (let i = 0; i < size; i++) {
    set(6, i, i % 2 === 0)
    set(i, 6, i % 2 === 0)
  }
  for (const [cx, cy] of [[3, 3], [size - 4, 3], [3, size - 4]] as const) {
    for (let dy = -4; dy <= 4; dy++) {
      for (let dx = -4; dx <= 4; dx++) {
        const x = cx + dx
        const y = cy + dy
        const distance = Math.max(Math.abs(dx), Math.abs(dy))
        if (x >= 0 && x < size && y >= 0 && y < size) set(x, y, distance !== 2 && distance !== 4)
      }
    }
  }
  const aligns = alignmentPositions(version, size)
  for (let i = 0; i < aligns.length; i++) {
    for (let j = 0; j < aligns.length; j++) {
      const isFinderCorner = (i === 0 && j === 0) || (i === 0 && j === aligns.length - 1) || (i === aligns.length - 1 && j === 0)
      if (isFinderCorner) continue
      for (let dy = -2; dy <= 2; dy++) {
        for (let dx = -2; dx <= 2; dx++) set(aligns[i]! + dx, aligns[j]! + dy, Math.max(Math.abs(dx), Math.abs(dy)) !== 1)
      }
    }
  }

  const drawFormat = (mask: number) => {
    const value = (FORMAT_BITS_M << 3) | mask
    let rem = value
    for (let i = 0; i < 10; i++) rem = (rem << 1) ^ ((rem >>> 9) * 0x537)
    const formatBits = ((value << 10) | rem) ^ 0x5412
    const bit = (i: number) => ((formatBits >>> i) & 1) !== 0
    for (let i = 0; i <= 5; i++) set(8, i, bit(i))
    set(8, 7, bit(6))
    set(8, 8, bit(7))
    set(7, 8, bit(8))
    for (let i = 9; i < 15; i++) set(14 - i, 8, bit(i))
    for (let i = 0; i < 8; i++) set(size - 1 - i, 8, bit(i))
    for (let i = 8; i < 15; i++) set(8, size - 15 + i, bit(i))
    set(8, size - 8, true)
  }
  drawFormat(0)

  if (version >= 7) {
    let rem = version
    for (let i = 0; i < 12; i++) rem = (rem << 1) ^ ((rem >>> 11) * 0x1f25)
    const versionBits = (version << 12) | rem
    for (let i = 0; i < 18; i++) {
      const dark = ((versionBits >>> i) & 1) !== 0
      const a = size - 11 + (i % 3)
      const b = Math.floor(i / 3)
      set(a, b, dark)
      set(b, a, dark)
    }
  }

  // the data, two columns at a time, zigzagging up and down from the right
  let index = 0
  for (let right = size - 1; right >= 1; right -= 2) {
    if (right === 6) right = 5
    for (let vertical = 0; vertical < size; vertical++) {
      for (let j = 0; j < 2; j++) {
        const x = right - j
        const isUpward = ((right + 1) & 2) === 0
        const y = isUpward ? size - 1 - vertical : vertical
        if (!isFunction[y]![x] && index < codewords.length * 8) {
          modules[y]![x] = ((codewords[index >>> 3]! >>> (7 - (index & 7))) & 1) === 1
          index++
        }
      }
    }
  }

  const applyMask = (mask: number) => {
    for (let y = 0; y < size; y++) {
      for (let x = 0; x < size; x++) {
        if (!isFunction[y]![x] && masked(mask, x, y)) modules[y]![x] = !modules[y]![x]
      }
    }
  }
  let best = 0
  let bestScore = Infinity
  for (let mask = 0; mask < 8; mask++) {
    applyMask(mask)
    drawFormat(mask)
    const score = penalty(modules)
    if (score < bestScore) {
      best = mask
      bestScore = score
    }
    applyMask(mask)
  }
  applyMask(best)
  drawFormat(best)
  return { size, modules }
}

const DARK = 0x000000
const LIGHT = 0xffffff
const UPPER_HALF = 0x2580

/** The module at (x, y), with `quiet` light modules around the code. */
function moduleAt(qr: QrCode, quiet: number, x: number, y: number): boolean {
  const mx = x - quiet
  const my = y - quiet
  return mx >= 0 && my >= 0 && mx < qr.size && my < qr.size && qr.modules[my]![mx]!
}

const BASE64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'

export function toBase64(bytes: Uint8Array): string {
  let out = ''
  for (let i = 0; i < bytes.length; i += 3) {
    const a = bytes[i]!
    const b = bytes[i + 1]
    const c = bytes[i + 2]
    const n = (a << 16) | ((b ?? 0) << 8) | (c ?? 0)
    out += BASE64[(n >>> 18) & 63]! + BASE64[(n >>> 12) & 63]!
    out += b === undefined ? '=' : BASE64[(n >>> 6) & 63]!
    out += c === undefined ? '=' : BASE64[n & 63]!
  }
  return out
}

/**
 * The code as a terminal Raster: one cell holds two modules, the upper half
 * block painted with the top one and its background with the bottom one, in
 * black and white whatever the terminal's theme, so the modules come out
 * square and the right way round.
 */
export function qrRaster(qr: QrCode, quiet = 2): { columns: number; rows: number; cells: string } {
  const columns = qr.size + quiet * 2
  const rows = Math.ceil(columns / 2)
  const words = new Uint32Array(columns * rows * 3)
  for (let row = 0; row < rows; row++) {
    for (let x = 0; x < columns; x++) {
      const at = (row * columns + x) * 3
      words[at] = UPPER_HALF
      words[at + 1] = moduleAt(qr, quiet, x, row * 2) ? DARK : LIGHT
      words[at + 2] = moduleAt(qr, quiet, x, row * 2 + 1) ? DARK : LIGHT
    }
  }
  // Uint32Array stores in the platform's order; every engine this runs on is little-endian
  return { columns, rows, cells: toBase64(new Uint8Array(words.buffer)) }
}

/** The code as SVG markup, dark modules on a white square. */
export function qrSvg(qr: QrCode, quiet = 4): string {
  const side = qr.size + quiet * 2
  const path: string[] = []
  for (let y = 0; y < qr.size; y++) {
    for (let x = 0; x < qr.size; x++) {
      if (qr.modules[y]![x]) path.push(`M${x + quiet} ${y + quiet}h1v1h-1z`)
    }
  }
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${side} ${side}" shape-rendering="crispEdges"><rect width="${side}" height="${side}" fill="#fff"/><path d="${path.join('')}" fill="#000"/></svg>`
}

files.hooks/setup.ts:
// What the setup tabs say and the commands they copy or run.

import type { ProxyAddress, ProxySetupTab, ProxyStatus } from '../types'

export const MAGIC_HOST = 'claude.proxy'

export const SETUP_TABS: { tab: ProxySetupTab; label: string; hotkey: string }[] = [
  { tab: 'browser', label: 'Browser', hotkey: '1' },
  { tab: 'ios', label: 'iOS', hotkey: '2' },
  { tab: 'android', label: 'Android', hotkey: '3' },
  { tab: 'cli', label: 'macOS / CLI', hotkey: '4' },
]

export type Browser = { name: string; app: string; slug: string }

/** Chromium browsers that honour --proxy-server and the SPKI allow-list. */
export const BROWSER_CANDIDATES: Browser[] = [
  { name: 'Google Chrome', app: 'Google Chrome.app', slug: 'chrome' },
  { name: 'Chrome Canary', app: 'Google Chrome Canary.app', slug: 'chrome-canary' },
  { name: 'Chromium', app: 'Chromium.app', slug: 'chromium' },
  { name: 'Microsoft Edge', app: 'Microsoft Edge.app', slug: 'edge' },
  { name: 'Brave', app: 'Brave Browser.app', slug: 'brave' },
]

export type SetupFacts = {
  status: ProxyStatus
  dataDir: string
  listen: 'local' | 'lan'
}

function proxyAddress(status: ProxyStatus): string {
  return `127.0.0.1:${status.port}`
}

/** The address a phone on the same network enters as its proxy server. */
export function phoneAddress(facts: SetupFacts): ProxyAddress | null {
  return facts.status.lan.find(entry => entry.isPrimary) ?? null
}

/** One client of a tab and exactly what goes into its proxy settings. */
export type ProxyTarget = {
  client: string
  /** What to enter as the server; null when this Mac has no address for it. */
  host: string | null
  port: number
  /** Where it goes, or what sets it. */
  how: string
  /** Reached over the network: needs Listen on = lan. */
  isRemote: boolean
}

export function proxyTargets(facts: SetupFacts, tab: ProxySetupTab): ProxyTarget[] {
  const port = facts.status.port
  const phone = phoneAddress(facts)?.address ?? null
  switch (tab) {
    case 'browser':
      return [{ client: 'Separate browser', host: '127.0.0.1', port, how: 'set by the Open button', isRemote: false }]
    case 'ios':
      return [
        { client: 'iOS Simulator', host: '127.0.0.1', port, how: 'macOS system proxy ("system proxy on")', isRemote: false },
        { client: 'iPhone / iPad', host: phone, port, how: 'Wi-Fi → (i) → Configure Proxy → Manual', isRemote: true },
      ]
    case 'android':
      return [
        { client: 'Android emulator', host: '10.0.2.2', port, how: 'set by "Android → proxy"', isRemote: false },
        { client: 'Android on USB', host: '127.0.0.1', port, how: 'set by "Android → proxy" (adb reverse)', isRemote: false },
        { client: 'Android on Wi-Fi', host: phone, port, how: 'Wi-Fi → Modify → Proxy: Manual', isRemote: true },
      ]
    default:
      return [{ client: 'curl, scripts, system proxy', host: '127.0.0.1', port, how: 'HTTPS_PROXY / -x / networksetup', isRemote: false }]
  }
}

/** What the phone steps say before step 1 when the phone cannot reach the proxy yet. */
function phonePreface(facts: SetupFacts): string {
  const phone = phoneAddress(facts)
  if (!phone) {
    return facts.status.lan.length === 0 && facts.status.phase !== 'running'
      ? 'Start the proxy to find the address the phone should use.\n\n'
      : 'This Mac has no address a phone could reach: connect it to Wi-Fi or Ethernet, on the same network as the phone.\n\n'
  }
  return facts.listen === 'lan'
    ? ''
    : 'First turn on **Listen on LAN** (the button above): the proxy listens on this Mac only now, so the phone cannot reach it.\n\n'
}

export function browserArgs(facts: SetupFacts, browser: Browser): string[] {
  const spki = facts.status.ca?.spki ?? []
  return [
    `--user-data-dir=${facts.dataDir}/browser/${browser.slug}`,
    `--proxy-server=http://${proxyAddress(facts.status)}`,
    // Chrome skips the proxy for localhost unless told otherwise.
    '--proxy-bypass-list=<-loopback>',
    `--ignore-certificate-errors-spki-list=${spki.join(',')}`,
    '--no-first-run',
    '--no-default-browser-check',
    `http://${MAGIC_HOST}/`,
  ]
}

export function shellQuote(text: string): string {
  return /^[\w@%+=:,./-]+$/.test(text) ? text : `'${text.replace(/'/g, `'\\''`)}'`
}

export function browserCommand(facts: SetupFacts, browser: Browser, appPath: string): string {
  return ['open', '-na', appPath, '--args', ...browserArgs(facts, browser)].map(shellQuote).join(' ')
}

export function systemProxyCommands(port: number, service = 'Wi-Fi'): { on: string; off: string } {
  const s = shellQuote(service)
  return {
    on: `networksetup -setwebproxy ${s} 127.0.0.1 ${port} && networksetup -setsecurewebproxy ${s} 127.0.0.1 ${port}`,
    off: `networksetup -setwebproxystate ${s} off && networksetup -setsecurewebproxystate ${s} off`,
  }
}

export function trustCommand(caPath: string): string {
  return `security add-trusted-cert -r trustRoot -k ~/Library/Keychains/login.keychain-db ${shellQuote(caPath)}`
}

export function untrustCommand(caPath: string): string {
  return `security remove-trusted-cert ${shellQuote(caPath)}`
}

export const ANDROID_NETWORK_CONFIG = `<!-- res/xml/network_security_config.xml -->
<network-security-config>
  <debug-overrides>
    <trust-anchors>
      <certificates src="user" />
    </trust-anchors>
  </debug-overrides>
</network-security-config>

<!-- AndroidManifest.xml, on <application> -->
android:networkSecurityConfig="@xml/network_security_config"`

/** The copyable commands each tab offers, by key. */
export function setupCommands(facts: SetupFacts): Record<string, string> {
  const port = facts.status.port
  const ca = facts.status.ca?.path ?? `${facts.dataDir}/ca/ca.pem`
  const proxy = systemProxyCommands(port)
  return {
    'sys-on': proxy.on,
    'sys-off': proxy.off,
    trust: trustCommand(ca),
    untrust: untrustCommand(ca),
    'sim-ca': `xcrun simctl keychain booted add-root-cert ${shellQuote(ca)}`,
    'adb-on': `adb shell settings put global http_proxy 10.0.2.2:${port}`,
    'adb-off': 'adb shell settings put global http_proxy :0',
    'android-config': ANDROID_NETWORK_CONFIG,
    curl: `curl -x http://${proxyAddress(facts.status)} --cacert ${shellQuote(ca)} https://example.com/`,
    env: [
      `export HTTPS_PROXY=http://${proxyAddress(facts.status)} HTTP_PROXY=http://${proxyAddress(facts.status)}`,
      `export NODE_EXTRA_CA_CERTS=${shellQuote(ca)} SSL_CERT_FILE=${shellQuote(ca)} REQUESTS_CA_BUNDLE=${shellQuote(ca)}`,
    ].join('\n'),
  }
}

export function browserGuide(facts: SetupFacts, found: readonly Browser[]): string {
  const browsers = found.length > 0 ? found.map(b => b.name).join(', ') : 'none (looked for Chrome, Chromium, Edge, Brave)'
  return `### A separate browser whose traffic all goes through the proxy

The button below starts a **new instance** of a Chromium browser with a profile of its own
(\`${facts.dataDir}/browser/…\`) that:

- goes through the proxy \`${proxyAddress(facts.status)}\`, **localhost included** (\`--proxy-bypass-list=<-loopback>\`);
- trusts the proxy's certificates by the SPKI hash of their key, so **nothing goes into the keychain**;
- leaves your everyday profile alone: logins, extensions and tabs stay apart, and the profile is kept between runs.

Found: ${browsers}.

It opens on \`http://${MAGIC_HOST}/\`: if that page shows, the browser is going through the proxy.
A yellow "unsupported command-line flag" bar is expected; it is how Chrome flags the trust switch.

**Firefox** (by hand): a separate profile (\`firefox -P\`), then Settings → Network Settings → Manual proxy
configuration, \`127.0.0.1\` port \`${facts.status.port}\` for HTTP and HTTPS. In \`about:config\` set
\`network.proxy.allow_hijacking_localhost = true\`. Import the CA under Settings → Privacy & Security → Certificates →
View Certificates → Authorities → Import (\`${facts.status.ca?.path ?? 'ca.pem'}\`) and tick "Trust this CA to identify websites".`
}

export function iosGuide(facts: SetupFacts): string {
  const phone = phoneAddress(facts)
  const device = !phone
    ? phonePreface(facts)
    : `${phonePreface(facts)}The iPhone must be on the same network as this Mac's ${phone.label}.

1. **Scan the QR code above** with the Camera app (or open \`http://${phone.address}:${facts.status.port}/\` in Safari)
   → "iOS: download profile" → Allow. This page needs no proxy setting yet.
2. **Settings → Profile Downloaded → Install** (the profile is unsigned; that is expected).
3. **Settings → General → About → Certificate Trust Settings** → turn on "${caName(facts)}".
4. **Settings → Wi-Fi → (i) next to the network → Configure Proxy → Manual**:
   Server \`${phone.address}\`, Port \`${facts.status.port}\`, Authentication off.
5. Done. Rows marked **CERT** in the list mean step 3 is missing or the app pins its certificates;
   such hosts can go into the "Hosts not to decrypt" option.

When you are done, set **Configure Proxy → Off** again, or the iPhone loses its network once the proxy stops.`
  return `### iOS Simulator

1. **"CA → simulators"** below adds the root certificate to every **booted** simulator
   (\`xcrun simctl keychain <udid> add-root-cert\`). Once per simulator is enough.
2. The simulator has no proxy settings of its own: it uses the **macOS system proxy**. Turn it on with
   "system proxy on" and turn it off ("off") when you are done. All of this Mac's traffic goes through
   the proxy meanwhile, so keep it on only while you debug.

### iPhone / iPad

${device}`
}

export function androidGuide(facts: SetupFacts): string {
  const phone = phoneAddress(facts)
  const device = !phone
    ? phonePreface(facts)
    : `${phonePreface(facts)}The phone must be on the same network as this Mac's ${phone.label}.

1. **Scan the QR code above** with the camera (or open \`http://${phone.address}:${facts.status.port}/\` in Chrome)
   → "Android: download certificate". This page needs no proxy setting yet.
2. **Settings → Security → Encryption & credentials → Install a certificate → CA certificate** → pick the downloaded file.
3. **Settings → Wi-Fi → long-press the network → Modify → Advanced → Proxy: Manual**:
   Hostname \`${phone.address}\`, Port \`${facts.status.port}\`.
4. When you are done, set **Proxy: None** again.

A phone on USB needs none of this: "Android → proxy" reaches it through \`adb reverse\`.`
  return `### Android emulator and USB devices

1. **"Android → proxy"** points every device \`adb devices\` lists at the proxy: an emulator at
   \`10.0.2.2:${facts.status.port}\` (an emulator's name for this Mac's localhost), a USB device at
   \`127.0.0.1:${facts.status.port}\` through \`adb reverse\`. The \`local\` mode is enough for both.
   **"Revert"** sets \`:0\` again; the mod also reverts by itself when the proxy stops and when the session ends.
2. **"Open CA page"** opens \`http://${MAGIC_HOST}/\` in the device's browser. Download "Android: download certificate",
   then **Settings → Security → Encryption & credentials → Install a certificate → CA certificate**.

### Android over Wi-Fi

${device}

### Apps and user CAs

Since Android 7, apps **do not trust** certificates the user installed. Chrome does; your app will show
**CERT** rows. Give its debug build a \`network_security_config\` ("config snippet"):

\`\`\`xml
${ANDROID_NETWORK_CONFIG}
\`\`\``
}

export function cliGuide(facts: SetupFacts): string {
  const ca = facts.status.ca?.path ?? 'ca.pem'
  return `### Trusting the CA on this Mac

Needed only when traffic does not come from the separate browser, for example from Safari or through the system proxy:

\`\`\`sh
${trustCommand(ca)}
\`\`\`

To undo: \`${untrustCommand(ca)}\`.

### The macOS system proxy (Safari, the simulator, native apps)

\`\`\`sh
${systemProxyCommands(facts.status.port).on}
# turn it off:
${systemProxyCommands(facts.status.port).off}
\`\`\`

\`networksetup -listallnetworkservices\` lists the service names (\`Wi-Fi\` here). If the proxy stops while
the system proxy is on, the Mac has no network until it is turned off.

### curl and scripts

\`\`\`sh
${setupCommands(facts).curl}
${setupCommands(facts).env}
\`\`\``
}

export function caName(facts: SetupFacts): string {
  return facts.status.ca?.subject.match(/CN=([^,]+)/)?.[1] ?? 'Claude Code Proxy CA'
}
